import{_ as s,c as a,d as t,o as e}from"./app-F_ELCBVL.js";const p={};function o(c,n){return e(),a("div",null,[...n[0]||(n[0]=[t(`<h1 id="rushwind-cms-—-三服务拓扑-core-领域层、双-bff-薄代理与一份契约的双面输出" tabindex="-1"><a class="header-anchor" href="#rushwind-cms-—-三服务拓扑-core-领域层、双-bff-薄代理与一份契约的双面输出"><span>RushWind CMS — 三服务拓扑：core 领域层、双 BFF 薄代理与一份契约的双面输出</span></a></h1><blockquote><p>本文回答一个问题：<strong>一个内容平台为什么要拆成 core-service + 双 BFF 三个进程？BFF 里为什么连一句 SQL 都找不到？同一份 proto 契约又怎么同时长出 REST 和 gRPC 两张脸、喂饱五个前端？</strong></p></blockquote><p><a href="https://github.com/tx7do/rushwind-cms" target="_blank" rel="noopener noreferrer">RushWind CMS</a> 是一套 Rust 全栈 Headless 内容平台。它的后端是三个进程：<strong>core-service</strong> 是唯一的领域层，独占 PostgreSQL 与 Redis，只对内暴露 gRPC；<strong>admin-api</strong> 与 <strong>app-api</strong> 是两道 BFF，对浏览器与小程序提供 REST + SSE。分工写成一条铁律（仓库根 <code>AGENTS.md</code>）：</p><blockquote><p><strong>BFF 不碰数据库</strong>：admin-api / app-api 只做协议转换与转发（生成代理 + 手写面）；数据访问只发生在 core-service。</p></blockquote><p>这句话的含金量在于&quot;只发生在&quot;——不是规范建议，是结构事实：BFF 的代码里不存在数据库连接。本文从启动序列讲到生成器，把这套拓扑的每个接缝拆开。</p><hr><h2 id="一、三服务分工-数据只有一个主人" tabindex="-1"><a class="header-anchor" href="#一、三服务分工-数据只有一个主人"><span>一、三服务分工：数据只有一个主人</span></a></h2><p>三个进程、四个端口，各管一段：</p><table><thead><tr><th>进程</th><th>端口</th><th>职责</th></tr></thead><tbody><tr><td>core-service</td><td>gRPC :6602</td><td>领域层：认证内核 + 全部领域服务，独占 PG/Redis，不对外暴露</td></tr><tr><td>admin-api</td><td>REST :6600 / SSE :6601</td><td>管理 BFF：后台全部路由</td></tr><tr><td>app-api</td><td>REST :6700 / SSE :6701</td><td>前台 BFF：门户、注册登录、游客评论、公开读</td></tr></tbody></table><p>core-service 的 <code>main.rs</code> 只有三件事——读配置、连库并引导、起 gRPC：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/services/core-service/src/main.rs</span></span>
<span class="line"><span class="token comment">//! The core domain service entry: loads the embedded config defaults</span></span>
<span class="line"><span class="token comment">//! (env overrides win), connects Postgres + Redis exclusively (the</span></span>
<span class="line"><span class="token comment">//! BFFs never touch the database), runs the fresh-database bootstrap</span></span>
<span class="line"><span class="token comment">//! (golden DDL + system seed + demo seed), and serves the domain gRPC</span></span>
<span class="line"><span class="token comment">//! face (:6602 by default).</span></span>
<span class="line"></span>
<span class="line"><span class="token attribute attr-name">#[tokio::main]</span></span>
<span class="line"><span class="token keyword">async</span> <span class="token keyword">fn</span> <span class="token function-definition function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">Result</span><span class="token operator">&lt;</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token class-name">Box</span><span class="token operator">&lt;</span><span class="token keyword">dyn</span> <span class="token namespace">std<span class="token punctuation">::</span>error<span class="token punctuation">::</span></span><span class="token class-name">Error</span><span class="token operator">&gt;&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">let</span> cfg <span class="token operator">=</span> <span class="token class-name">Config</span><span class="token punctuation">::</span><span class="token function">load</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">let</span> state <span class="token operator">=</span> <span class="token class-name">Arc</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token class-name">AppState</span><span class="token punctuation">::</span><span class="token function">connect</span><span class="token punctuation">(</span>cfg<span class="token punctuation">.</span><span class="token function">clone</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token namespace">store<span class="token punctuation">::</span>bootstrap<span class="token punctuation">::</span></span><span class="token function">run</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>state<span class="token punctuation">.</span>db<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">let</span> addr<span class="token punctuation">:</span> <span class="token namespace">std<span class="token punctuation">::</span>net<span class="token punctuation">::</span></span><span class="token class-name">SocketAddr</span> <span class="token operator">=</span> cfg<span class="token punctuation">.</span>grpc_addr<span class="token punctuation">.</span><span class="token function">parse</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">...</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">let</span> listener <span class="token operator">=</span> <span class="token namespace">tokio<span class="token punctuation">::</span>net<span class="token punctuation">::</span></span><span class="token class-name">TcpListener</span><span class="token punctuation">::</span><span class="token function">bind</span><span class="token punctuation">(</span>addr<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token namespace">tonic<span class="token punctuation">::</span>transport<span class="token punctuation">::</span></span><span class="token class-name">Server</span><span class="token punctuation">::</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">add_routes</span><span class="token punctuation">(</span><span class="token namespace">server<span class="token punctuation">::</span></span><span class="token function">registry</span><span class="token punctuation">(</span>state<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">serve_with_incoming</span><span class="token punctuation">(</span><span class="token namespace">tokio_stream<span class="token punctuation">::</span>wrappers<span class="token punctuation">::</span></span><span class="token class-name">TcpListenerStream</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span>listener<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token class-name">Ok</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>空库引导值得一格：数据库全新时自动跑四段 SQL——schema、系统种子、菜单种子、演示数据。已有的库一行不动，演进交给黄金 DDL 管线：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/crates/store/src/bootstrap.rs</span></span>
<span class="line"><span class="token comment">/// Applies schema + system seed + demo seed when the database is fresh.</span></span>
<span class="line"><span class="token comment">/// Existing databases (already carrying the schema) are left untouched —</span></span>
<span class="line"><span class="token comment">/// the golden-DDL pipeline owns evolution.</span></span>
<span class="line"><span class="token keyword">pub</span> <span class="token keyword">async</span> <span class="token keyword">fn</span> <span class="token function-definition function">run</span><span class="token punctuation">(</span>db<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token class-name">DatabaseConnection</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">Result</span><span class="token operator">&lt;</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token namespace">sea_orm<span class="token punctuation">::</span></span><span class="token class-name">DbErr</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token keyword">crate</span><span class="token module-declaration namespace"><span class="token punctuation">::</span>tables_present</span><span class="token punctuation">(</span>db<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token class-name">Ok</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token function">exec_statements</span><span class="token punctuation">(</span>db<span class="token punctuation">,</span> <span class="token keyword">crate</span><span class="token punctuation">::</span><span class="token constant">SCHEMA_SQL</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">exec_statements</span><span class="token punctuation">(</span>db<span class="token punctuation">,</span> <span class="token keyword">crate</span><span class="token punctuation">::</span><span class="token constant">SEED_SQL</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">exec_statements</span><span class="token punctuation">(</span>db<span class="token punctuation">,</span> <span class="token keyword">crate</span><span class="token punctuation">::</span><span class="token constant">MENUS_SEED_SQL</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">exec_statements</span><span class="token punctuation">(</span>db<span class="token punctuation">,</span> <span class="token keyword">crate</span><span class="token punctuation">::</span><span class="token constant">DEMO_DATA_SQL</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token class-name">Ok</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>cargo run -p core-service</code> 连上空库，等它跑完，一个带演示数据的完整内容平台就在 :6602 后面了——&quot;从克隆到能点&quot;的距离被压到一个启动序列。</p><p>界面上它长这样：管理后台的帖子管理、标签管理，与 Next.js 内容门户，全部消费同一个后端栈：</p><table><thead><tr><th style="text-align:center;">管理后台 · 帖子管理</th><th style="text-align:center;">管理后台 · 标签管理</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="https://tx7do.github.io/assets/images/rushwind-cms/admin-posts.webp" alt="管理后台 · 帖子管理"></td><td style="text-align:center;"><img src="https://tx7do.github.io/assets/images/rushwind-cms/admin-tags.webp" alt="管理后台 · 标签管理"></td></tr></tbody></table><p><strong>前台 · 内容门户（Next.js）</strong>——四套前台（React / Vue / Taro / Flutter）共用 app-api 这一道 BFF：</p><p><img src="https://tx7do.github.io/assets/images/rushwind-cms/app-home.webp" alt="前台 · 内容门户（Next.js）"></p><h2 id="二、一份契约-两张脸" tabindex="-1"><a class="header-anchor" href="#二、一份契约-两张脸"><span>二、一份契约，两张脸</span></a></h2><p>三个进程对外的全部接口，来自同一棵 proto 树。契约 crate 的 <code>build.rs</code> 是一个纯配置值——它声明两件事：<strong>gRPC 面要生成（<code>tonic: true</code>）</strong>，以及 <strong>REST 面按 root prefix 切成两张</strong>：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/crates/proto/build.rs</span></span>
<span class="line"><span class="token namespace">rushwind_proto_build<span class="token punctuation">::</span></span><span class="token function">run</span><span class="token punctuation">(</span><span class="token namespace">rushwind_proto_build<span class="token punctuation">::</span></span><span class="token class-name">Build</span> <span class="token punctuation">{</span></span>
<span class="line">    dep_data_files<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token punctuation">[</span></span>
<span class="line">        <span class="token string">&quot;pagination/v1/pagination.proto&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;google/api/httpbody.proto&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    auth_free<span class="token punctuation">:</span> <span class="token constant">AUTH_FREE</span><span class="token punctuation">,</span></span>
<span class="line">    redact_plan_expr<span class="token punctuation">:</span> <span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token string">&quot;crate::redact_plan()&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    tonic<span class="token punctuation">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">    faces<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token punctuation">[</span></span>
<span class="line">        <span class="token namespace">rushwind_proto_build<span class="token punctuation">::</span></span><span class="token class-name">Face</span> <span class="token punctuation">{</span></span>
<span class="line">            label<span class="token punctuation">:</span> <span class="token string">&quot;admin&quot;</span><span class="token punctuation">,</span></span>
<span class="line">            module_file<span class="token punctuation">:</span> <span class="token string">&quot;admin_gen.rs&quot;</span><span class="token punctuation">,</span></span>
<span class="line">            root_prefix<span class="token punctuation">:</span> <span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token string">&quot;admin/service/v1/&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            module_path<span class="token punctuation">:</span> <span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token string">&quot;crate::gen_admin::&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token namespace">rushwind_proto_build<span class="token punctuation">::</span></span><span class="token class-name">Face</span> <span class="token punctuation">{</span></span>
<span class="line">            label<span class="token punctuation">:</span> <span class="token string">&quot;app&quot;</span><span class="token punctuation">,</span></span>
<span class="line">            module_file<span class="token punctuation">:</span> <span class="token string">&quot;app_gen.rs&quot;</span><span class="token punctuation">,</span></span>
<span class="line">            root_prefix<span class="token punctuation">:</span> <span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token string">&quot;app/service/v1/&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            module_path<span class="token punctuation">:</span> <span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token string">&quot;crate::gen_app::&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">..</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>为什么要切两张？模块文档给了唯一理由：<strong>admin 与 app 的 BFF 存在同名服务</strong>（两边各有一个 <code>CategoryService</code>、<code>CommentService</code>，语义不同），两张面按 root prefix 切片、各指各的模块，不能共享。切片是字节级保真的可达性遍历——每张面只含自己前缀下的契约，挂到 <code>crate::gen_admin</code> / <code>crate::gen_app</code>。</p><p>同一棵契约树于是长出三样东西：</p><ul><li><strong>prost/pbjson 类型</strong>（两个 BFF 与 core 共用同一套消息类型，&quot;BFF 与领域方法共享消息类型，代理层零映射&quot;）；</li><li><strong>tonic gRPC 面</strong>——core-service 的全部领域服务实现的是它；</li><li><strong>gen-http REST 面</strong>——两张，分别是两个 BFF 的路由/绑定/trait/挂载产物。</li></ul><p>类型一树，三处消费。契约改一处，gRPC 与两张 REST 面同时重算——没有&quot;REST 改了 gRPC 忘了&quot;这种事，因为它们不是两份代码，是同一份契约的两次投影。</p><h2 id="三、薄代理-bff-是一张生成的宏表" tabindex="-1"><a class="header-anchor" href="#三、薄代理-bff-是一张生成的宏表"><span>三、薄代理：BFF 是一张生成的宏表</span></a></h2><p>BFF 里的领域路由不是手写的转发函数，是一张<strong>生成</strong>的宏表。每个 proxy impl 长这样：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/services/admin-api/src/services/proxies.rs（生成物）</span></span>
<span class="line"><span class="token comment">//! Generated thin-BFF proxies — a table of passthrough_proxy! invocations</span></span>
<span class="line"><span class="token comment">//! ... DO NOT EDIT; regenerate via scripts/gen-proxies.py</span></span>
<span class="line"></span>
<span class="line"><span class="token macro property">passthrough_proxy!</span><span class="token punctuation">(</span></span>
<span class="line">    <span class="token namespace">services<span class="token punctuation">::</span></span>admin_face <span class="token keyword">for</span> <span class="token class-name">AccessKeyProxy</span> <span class="token punctuation">{</span></span>
<span class="line">        client<span class="token punctuation">:</span> <span class="token namespace">access_v1<span class="token punctuation">::</span></span><span class="token class-name">AccessKeyServiceClient</span><span class="token operator">&lt;</span><span class="token class-name">Channel</span><span class="token operator">&gt;</span><span class="token punctuation">,</span></span>
<span class="line">        behaviors<span class="token punctuation">:</span> behaviors<span class="token punctuation">,</span></span>
<span class="line">        methods<span class="token punctuation">:</span> <span class="token punctuation">[</span></span>
<span class="line">            pass <span class="token function">list_access_keys</span><span class="token punctuation">(</span><span class="token class-name">ListAccessKeysRequest</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">ListAccessKeysResponse</span><span class="token punctuation">,</span></span>
<span class="line">            pass <span class="token function">create_access_key</span><span class="token punctuation">(</span><span class="token class-name">CreateAccessKeyRequest</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">CreateAccessKeyResponse</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token punctuation">...</span></span>
<span class="line">        <span class="token punctuation">]</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>宏的方法有四种形态（<code>proxy_kit.rs</code> 的自述）：</p><ul><li><strong><code>pass</code></strong>——普通透传：带上操作者戳转发，原样返回领域的响应；</li><li><strong><code>drop</code></strong>——转发但丢弃响应体（BFF 脸返回 <code>Empty</code>，领域返回实体）；</li><li><strong><code>stub</code></strong>——契约有这个方法、领域还没落地：恒答 NOT_IMPLEMENTED；</li><li><strong><code>hand</code></strong>——委托给 BFF 手写行为模块（裸转发带不动的 BFF 专属语义）。</li></ul><p><code>pass</code> 分支的全部实现，就是这一段：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/services/admin-api/src/services/proxy_kit.rs</span></span>
<span class="line"><span class="token comment">// pass — the operator-stamped forward, the inner response back.</span></span>
<span class="line"><span class="token punctuation">(</span><span class="token operator">@</span>body pass <span class="token variable">$method</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">ident</span><span class="token punctuation">(</span><span class="token variable">$req</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">ty</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token variable">$resp</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">ty</span><span class="token punctuation">,</span></span>
<span class="line">    client<span class="token punctuation">:</span> <span class="token variable">$client</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">ty</span><span class="token punctuation">,</span> behaviors<span class="token punctuation">:</span> <span class="token variable">$behaviors</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">ident</span><span class="token punctuation">,</span></span>
<span class="line">    state<span class="token punctuation">:</span> <span class="token variable">$state</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">expr</span><span class="token punctuation">,</span> ctx<span class="token punctuation">:</span> <span class="token variable">$ctx</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">expr</span><span class="token punctuation">,</span> msg<span class="token punctuation">:</span> <span class="token variable">$msg</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">expr</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">let</span> <span class="token keyword">mut</span> core <span class="token operator">=</span> <span class="token operator">&lt;</span><span class="token variable">$client</span><span class="token operator">&gt;</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token variable">$state</span><span class="token punctuation">.</span>core_channel<span class="token punctuation">.</span><span class="token function">clone</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token class-name">Ok</span><span class="token punctuation">(</span>core</span>
<span class="line">            <span class="token punctuation">.</span><span class="token variable">$method</span><span class="token punctuation">(</span><span class="token variable">$crate</span><span class="token punctuation">::</span><span class="token namespace">services<span class="token punctuation">::</span></span><span class="token function">with_operator</span><span class="token punctuation">(</span><span class="token variable">$ctx</span><span class="token punctuation">,</span> <span class="token variable">$msg</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">            <span class="token punctuation">.</span><span class="token keyword">await</span></span>
<span class="line">            <span class="token punctuation">.</span><span class="token function">map_err</span><span class="token punctuation">(</span><span class="token variable">$crate</span><span class="token punctuation">::</span><span class="token namespace">services<span class="token punctuation">::</span></span>map_status<span class="token punctuation">)</span><span class="token operator">?</span></span>
<span class="line">            <span class="token punctuation">.</span><span class="token function">into_inner</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这张表是脚本（<code>gen-proxies.py</code>）从契约生成的——admin 侧 71 个 proxy impl、app 侧 12 个，文件头一行 DO NOT EDIT。<strong>BFF 的&quot;薄&quot;是生成的，不是自觉的</strong>：没有人为每个新接口手写一遍转发样板，也就没有人在转发层夹带私货的机会。</p><p><code>hand</code> 形态最有代表性的是 app 侧的写方法——C 端 BFF 对内容写操作直接拒绝：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/services/app-api/src/services/proxies.rs</span></span>
<span class="line">hand <span class="token function">create</span><span class="token punctuation">(</span><span class="token namespace">content_v1<span class="token punctuation">::</span></span><span class="token class-name">CreatePageRequest</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token namespace">content_v1<span class="token punctuation">::</span></span><span class="token class-name">Page</span> <span class="token operator">=&gt;</span> forbidden_mutation<span class="token punctuation">,</span></span>
<span class="line">hand <span class="token function">update</span><span class="token punctuation">(</span><span class="token namespace">content_v1<span class="token punctuation">::</span></span><span class="token class-name">UpdatePageRequest</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token namespace">content_v1<span class="token punctuation">::</span></span><span class="token class-name">Page</span> <span class="token operator">=&gt;</span> forbidden_mutation<span class="token punctuation">,</span></span>
<span class="line">hand <span class="token function">delete</span><span class="token punctuation">(</span><span class="token namespace">content_v1<span class="token punctuation">::</span></span><span class="token class-name">DeletePageRequest</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token namespace">pbjson_types<span class="token punctuation">::</span></span><span class="token class-name">Empty</span> <span class="token operator">=&gt;</span> forbidden_mutation<span class="token punctuation">,</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>同一个领域服务，admin 脸 <code>pass</code> 全放行，app 脸写方法逐个钉成 403——BFF 的差异化语义（谁能写、谁只能读）收敛在代理表的一列动词上。</p><p><code>stub</code> 形态则是诚实的进度表态：契约先行于实现时，未落地的领域方法在 BFF 脸上明确回答 NOT_IMPLEMENTED，而不是静默 404 或 500。</p><h2 id="四、认证链在-core-刷新轮换是一次-lua-原子操作" tabindex="-1"><a class="header-anchor" href="#四、认证链在-core-刷新轮换是一次-lua-原子操作"><span>四、认证链在 core：刷新轮换是一次 Lua 原子操作</span></a></h2><p>认证内核住在 core-service。登录链的自述（<code>authentication_service.rs</code> 文件头）：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">//! * Login (password grant): tenant resolve → credential verify (AES</span></span>
<span class="line"><span class="token comment">//!   unwrap + bcrypt + dummy equalizer) → user status → permission gate</span></span>
<span class="line"><span class="token comment">//!   (sys:access_backend / sys:access_app per client type) → HS256</span></span>
<span class="line"><span class="token comment">//!   access JWT + opaque refresh, registered in the \`gwc:\` key family;</span></span>
<span class="line"><span class="token comment">//!   refresh grant: verify-and-revoke rotation then re-mint.</span></span>
<span class="line"><span class="token comment">//! * Logout: revokes every token of the user (SCAN prefix family).</span></span>
<span class="line"><span class="token comment">//! * ValidateToken: the BFF session check (whitelist + blacklist).</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>口令侧三件套照旧：应用层 AES 加密传输、bcrypt 哈希存储、<strong>恒时假校验</strong>（对不存在的用户跑一遍 dummy 哈希比对，让&quot;探测哪些用户名存在&quot;在时间侧信道上失效）。会话侧的键族按客户端类型与令牌种类分开：<code>gwc:at:{client}:{uid}:{jti}</code>、<code>gwc:rt:{client}:{uid}:{jti}</code>、黑名单 <code>gwc:bl:{jti}</code>。</p><p>最能代表&quot;这种事该住在哪一层&quot;的是刷新轮换。access token 与 refresh token 成对登记，刷新时<strong>验旧、吊旧、发新必须是原子的</strong>——两个请求同时拿同一个 refresh token 刷新，只能成功一个。这靠一段 Redis Lua 脚本保证：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/services/core-service/src/token.rs</span></span>
<span class="line"><span class="token keyword">const</span> <span class="token constant">VERIFY_AND_REVOKE</span><span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token keyword">str</span> <span class="token operator">=</span> <span class="token string">r#&quot;</span>
<span class="line">local rtKey = KEYS[1]</span>
<span class="line">local atKey = KEYS[2]</span>
<span class="line">local refreshToken = ARGV[1]</span>
<span class="line">local stored = redis.call(&#39;GET&#39;, rtKey)</span>
<span class="line">if not stored or stored ~= refreshToken then</span>
<span class="line">    return 0</span>
<span class="line">end</span>
<span class="line">redis.call(&#39;DEL&#39;, rtKey)</span>
<span class="line">redis.call(&#39;DEL&#39;, atKey)</span>
<span class="line">return 1</span>
<span class="line">&quot;#</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>GET 比对与两把 DEL 在脚本里一次执行，Redis 单线程模型天然串行化——没有竞态窗口。轮换后旧 access token 一起作废，&quot;刷新令牌泄露&quot;的损害窗口被压到一次使用。</p><p>BFF 这边不碰会话存储，它的鉴权门是<strong>两段式</strong>：本地先做 HS256 验签（格式对不对、签名过不过期，纯 CPU），会话校验阶段经适配器<strong>远程调 core 的 ValidateToken</strong>（白名单 + 黑名单的 verdict 只有一个来源）：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/crates/auth/src/lib.rs</span></span>
<span class="line"><span class="token keyword">let</span> claims <span class="token operator">=</span> <span class="token keyword">match</span> <span class="token namespace">rushwind_authn_gate<span class="token punctuation">::</span></span><span class="token function">authenticate_and_check_session</span><span class="token punctuation">(</span></span>
<span class="line">    auth<span class="token punctuation">.</span><span class="token function">as_ref</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> checker<span class="token punctuation">.</span><span class="token function">as_ref</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>headers<span class="token punctuation">,</span> bearer<span class="token punctuation">.</span><span class="token function">as_deref</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name">Ok</span><span class="token punctuation">(</span>claims<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> claims<span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">Err</span><span class="token punctuation">(</span>err<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token namespace">rushwind_http_binding<span class="token punctuation">::</span>envelope<span class="token punctuation">::</span></span><span class="token function">error_response</span><span class="token punctuation">(</span><span class="token function">unauthorized</span><span class="token punctuation">(</span>package<span class="token punctuation">,</span> err<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">req<span class="token punctuation">.</span><span class="token function">extensions_mut</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">insert</span><span class="token punctuation">(</span>claims<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">next<span class="token punctuation">.</span><span class="token function">run</span><span class="token punctuation">(</span>req<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>免鉴权白名单同样在契约 crate 里编译期成形（<code>auth_free.rs</code>：admin 10 条、app 27 条，<code>(service 全名, 方法名)</code> 二元组），<code>build.rs</code> 消费它生成公开/门内双路由树——白名单是产物，不是配置文件，改它就是改代码，review 看得见。</p><h2 id="五、横切件-分页管线与-sse-扇出" tabindex="-1"><a class="header-anchor" href="#五、横切件-分页管线与-sse-扇出"><span>五、横切件：分页管线与 SSE 扇出</span></a></h2><p><strong>分页</strong>。领域服务里没有一处手写的 count+offset。repo 侧只有一个 9 行的桥接文件，管线本体在框架：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/crates/store/src/paging.rs（全文）</span></span>
<span class="line"><span class="token comment">//! The deployment bridge to the framework paging pipeline</span></span>
<span class="line"><span class="token comment">//! (\`rushwind-storage-seaorm-support\`): ...</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">pub</span> <span class="token keyword">use</span> <span class="token namespace">rushwind_storage_seaorm_support<span class="token punctuation">::</span>paging<span class="token punctuation">::</span></span>fetch_paged<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>fetch_paged</code> 收一个 <code>Select</code> 基座和生成的 <code>PagingRequest</code>，内部完成过滤绑定（按列类型匹配算子：exact / in / gt / contains / icontains / range……）、count、切片。core-service 服务层 35 处调用，全是同一形状——分页参数的拼写（<code>page / pageSize / noPaging / orderBy / query</code>）全仓只有一个定义处。</p><p><strong>SSE</strong>。core 领域服务产生&quot;推给哪些人&quot;的事件后，经 gRPC 响应的 metadata 回传给 BFF 扇出——base64 包着的 JSON 事件列表：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/services/admin-api/src/services/internal_message.rs</span></span>
<span class="line"><span class="token comment">// The SSE fan-out: the payload metadata carries the base64 of a</span></span>
<span class="line"><span class="token comment">// JSON event list [{uid, payload}, …] — decoded here, each event</span></span>
<span class="line"><span class="token comment">// pushed to its user&#39;s stream.</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token keyword">let</span> <span class="token class-name">Some</span><span class="token punctuation">(</span>wire<span class="token punctuation">)</span> <span class="token operator">=</span> resp<span class="token punctuation">.</span><span class="token function">metadata</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&quot;x-sse-payload&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">and_then</span><span class="token punctuation">(</span><span class="token closure-params"><span class="token closure-punctuation punctuation">|</span>v<span class="token closure-punctuation punctuation">|</span></span> v<span class="token punctuation">.</span><span class="token function">to_str</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">ok</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">let</span> decoded <span class="token operator">=</span> <span class="token namespace">base64<span class="token punctuation">::</span>engine<span class="token punctuation">::</span>general<span class="token punctuation">::</span></span><span class="token constant">STANDARD</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">decode</span><span class="token punctuation">(</span>wire<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">ok</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">and_then</span><span class="token punctuation">(</span><span class="token closure-params"><span class="token closure-punctuation punctuation">|</span>b<span class="token closure-punctuation punctuation">|</span></span> <span class="token namespace">serde_json<span class="token punctuation">::</span></span><span class="token function">from_slice</span><span class="token punctuation">::</span><span class="token operator">&lt;</span><span class="token namespace">serde_json<span class="token punctuation">::</span></span><span class="token class-name">Value</span><span class="token operator">&gt;</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>b<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">ok</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token keyword">let</span> <span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token namespace">serde_json<span class="token punctuation">::</span></span><span class="token class-name">Value</span><span class="token punctuation">::</span><span class="token class-name">Array</span><span class="token punctuation">(</span>events<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">=</span> decoded <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">for</span> ev <span class="token keyword">in</span> events <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">let</span> uid <span class="token operator">=</span> ev<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&quot;uid&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">and_then</span><span class="token punctuation">(</span><span class="token closure-params"><span class="token closure-punctuation punctuation">|</span>v<span class="token closure-punctuation punctuation">|</span></span> v<span class="token punctuation">.</span><span class="token function">as_u64</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">unwrap_or</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">as</span> <span class="token keyword">u32</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token keyword">let</span> payload <span class="token operator">=</span> ev<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&quot;payload&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">cloned</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">unwrap_or_default</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token keyword">if</span> uid <span class="token operator">&gt;</span> <span class="token number">0</span> <span class="token operator">&amp;&amp;</span> payload<span class="token punctuation">.</span><span class="token function">is_object</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token keyword">let</span> body <span class="token operator">=</span> <span class="token namespace">serde_json<span class="token punctuation">::</span></span><span class="token function">to_string</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>payload<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">unwrap_or_else</span><span class="token punctuation">(</span><span class="token closure-params"><span class="token closure-punctuation punctuation">|</span>_<span class="token closure-punctuation punctuation">|</span></span> <span class="token string">&quot;{}&quot;</span><span class="token punctuation">.</span><span class="token function">to_string</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                <span class="token keyword">self</span><span class="token punctuation">.</span>state<span class="token punctuation">.</span>hub<span class="token punctuation">.</span><span class="token function">publish</span><span class="token punctuation">(</span>uid<span class="token punctuation">,</span> body<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>领域层不需要知道 SSE 的存在——它只是在 gRPC 响应上多带了一份收件人列表；BFF 的 Hub 按 uid 分发；连接侧再过一道归属校验：<code>?stream=</code> 参数必须等于令牌的 userId，否则 <code>FORBIDDEN: stream user mismatch</code>，循环里还要再滤一次 <code>user_id != uid</code> 的事件。&quot;谁的事件推给谁&quot;有两层检查，中间层的广播对订阅者不可见。</p><h2 id="六、五个前端与两份清单" tabindex="-1"><a class="header-anchor" href="#六、五个前端与两份清单"><span>六、五个前端与两份清单</span></a></h2><p>五个前端（管理后台 admin-react、门户 Next.js、门户 Nuxt、Taro 小程序、Flutter 应用）以<strong>快照</strong>形式随仓同步。快照的治理是双清单：</p><ul><li><strong><code>MANIFEST.sha256</code></strong>——快照终态的门：树上每个文件的哈希。手改任何一个文件，<code>--check</code> 立刻红；</li><li><strong><code>UPSTREAM.sha256</code></strong>——上游基线：同步时（品牌覆写<strong>之前</strong>）的上游哈希，用于检测&quot;上游源仓是否又动了&quot;。</li></ul><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># frontend/admin/sync-frontend.sh --check 的两道判</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token assign-left variable">d</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable"><span class="token variable">$(</span><span class="token function">diff</span> <span class="token parameter variable">-u</span> <span class="token string">&quot;<span class="token variable">$MANIFEST</span>&quot;</span> <span class="token operator">&lt;</span><span class="token punctuation">(</span>hash_tree <span class="token string">&quot;<span class="token variable">$DST</span>&quot;</span><span class="token punctuation">)</span> <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span><span class="token variable">)</span></span>&quot;</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">  <span class="token builtin class-name">echo</span> <span class="token string">&quot;OK: frontend/admin/<span class="token variable">$FRONTEND</span>/ matches <span class="token variable">$FRONTEND</span>.MANIFEST.sha256&quot;</span></span>
<span class="line"><span class="token keyword">else</span></span>
<span class="line">  <span class="token builtin class-name">echo</span> <span class="token string">&quot;ERROR: ... (hand-edit? run sync-frontend.sh <span class="token variable">$FRONTEND</span> to rebuild)&quot;</span> <span class="token operator">&gt;</span><span class="token file-descriptor important">&amp;2</span></span>
<span class="line">  <span class="token assign-left variable">status</span><span class="token operator">=</span><span class="token number">1</span>        <span class="token comment"># 手改 → 退出码 1</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"><span class="token comment"># 漂移检测：源仓在时对比上游基线（CI 无源仓时自跳过）。</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token operator">!</span> <span class="token function">diff</span> <span class="token parameter variable">-u</span> <span class="token string">&quot;<span class="token variable">$UPSTREAM_MANIFEST</span>&quot;</span> <span class="token operator">&lt;</span><span class="token punctuation">(</span>upstream_hash<span class="token punctuation">)</span> <span class="token operator">&gt;</span>/dev/null<span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">  <span class="token punctuation">..</span>. <span class="token assign-left variable">status</span><span class="token operator">=</span><span class="token number">2</span>    <span class="token comment"># 上游漂移 → 退出码 2</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>退出码分开了两种病因：<strong>手改快照</strong>（退出 1，必须重建）与<strong>上游有新版</strong>（退出 2，该同步了）。CI 里它们都是门，本地则是有用的信号。</p><p>快照唯一被允许的对源偏离是<strong>品牌覆写</strong>：同步后打一层 RushWind 品牌（logo / favicon / 文案 / meta），能改什么在一个登记表里逐条列明——logo 与二进制资产、公司名与链接、系统标题与版权行、<code>index.html</code> meta、env 应用标题。替换表是逐条显式声明，<strong>不做全局盲替换</strong>；设计 token、代码注释、树内冻结文档明确列为禁区，保持上游原样。双清单钉的是覆写之后的终态——diff 与登记表严格对账，多一行少一行都过不了门。</p><p>于是&quot;五个前端接同一个后端&quot;这件事的工程形态是：<strong>同步是唯一入口，覆写是唯一偏离，清单是唯一裁判</strong>。前端升级 = 跑一次同步脚本 + 复核登记表，而不是五次手工合并。</p><h2 id="七、e2e-三服务栈上的-125-个断言" tabindex="-1"><a class="header-anchor" href="#七、e2e-三服务栈上的-125-个断言"><span>七、E2E：三服务栈上的 125 个断言</span></a></h2><p>这套拓扑对不对，最后由一个脚本裁决。<code>backend/scripts/e2e-test.sh</code> 在三服务栈全起后跑 <strong>125 个断言点</strong>、11 个覆盖节：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function-name function">check</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">if</span> <span class="token punctuation">[</span><span class="token punctuation">[</span> <span class="token string">&quot;<span class="token variable">$3</span>&quot;</span> <span class="token operator">==</span> *<span class="token string">&quot;<span class="token variable">$2</span>&quot;</span>* <span class="token punctuation">]</span><span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span> ok<span class="token punctuation">;</span> <span class="token keyword">else</span> fail<span class="token punctuation">;</span> <span class="token keyword">fi</span><span class="token punctuation">;</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token comment"># ……收尾打印 结果: PASS=$PASS FAIL=$FAIL</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>11 节覆盖：验证码与登录链（含错误密码反枚举）、门控路由（无 token / 假 token 的 401 信封形状）、13 个模块的种子数据读、CRUD 写路径、刷新轮换与登出全吊销、app 面（注册 / 游客评论 / 公开读）、权限与审计、聚合面、multipart 文件上传下载（MinIO）、SSE 与 CORS、以及边界面（Range 206/416、草稿不可见、待审评论不可见、注册链跨租户回退）。</p><p>值得注意的不只是数量，是<strong>断言的层级</strong>：认证链的断言（fresh jti、轮换后旧 token 401、登出全吊销）打的是 core 的会话语义；门控路由的断言打的是 BFF 的门；草稿不可见打的是领域规则。三服务的每一道接缝，都有一节断言对着它。</p><h2 id="八、机制-×-关键决策-×-失败模式" tabindex="-1"><a class="header-anchor" href="#八、机制-×-关键决策-×-失败模式"><span>八、机制 × 关键决策 × 失败模式</span></a></h2><table><thead><tr><th>机制</th><th>关键决策</th><th>失败模式（若无此决策）</th></tr></thead><tbody><tr><td>core 独占数据</td><td>BFF 无数据库连接，数据访问单点</td><td>两个 BFF 各自直连库，事务与缓存口径分裂</td></tr><tr><td>契约双面</td><td>一棵契约树产出 tonic + 两张 gen-http 面</td><td>REST 与 gRPC 两套接口定义漂移</td></tr><tr><td>face 切片</td><td>按 root prefix 切 admin/app，同名服务各指各的模块</td><td>同名 <code>CategoryService</code> 在一张面里冲突</td></tr><tr><td>生成代理表</td><td><code>passthrough_proxy!</code> 四形态，gen-proxies.py 产物</td><td>转发层手写膨胀，BFF 私货与样板并存</td></tr><tr><td>stub 形态</td><td>契约先行，未落地方法明确 NOT_IMPLEMENTED</td><td>前端对半成品接口得到静默 404</td></tr><tr><td>Lua 原子轮换</td><td>验旧/吊旧/发新一次脚本执行</td><td>并发刷新竞态，refresh token 重放</td></tr><tr><td>两段式门</td><td>本地验签 + core 远程 ValidateToken</td><td>会话黑名单两处维护，吊销不及时</td></tr><tr><td>白名单进构建</td><td>AUTH_FREE 是代码，消费于 build.rs</td><td>公开路由靠配置文件，加路由忘配白名单</td></tr><tr><td>SSE metadata 扇出</td><td>领域只带收件人列表，BFF 分发+双重过滤</td><td>领域层耦合推送细节；事件串台</td></tr><tr><td>双清单快照</td><td>MANIFEST 终态门 + UPSTREAM 漂移基线，退出码分病因</td><td>前端快照被顺手修补，与上游渐行渐远</td></tr></tbody></table><p>三服务拓扑的成本是真实的：多两个进程、多一层 gRPC 边界、部署从一变三。买到的也是真实的：<strong>领域逻辑只有一个主人，BFF 薄到可以整体生成，契约的每次变更对 REST、gRPC、五个前端同时生效</strong>。什么时候值得付这个成本？当消费端的形态开始分化——管理后台与小程序要的不仅是不同界面，而是不同的权限面与错误面——BFF 就不再是架构品味，而是必需品。</p><hr><p>项目地址：<a href="https://gitee.com/tx7do/rushwind-cms" target="_blank" rel="noopener noreferrer">Gitee</a> ｜ <a href="https://github.com/tx7do/rushwind-cms" target="_blank" rel="noopener noreferrer">GitHub</a></p><p>相关项目：</p><ul><li><strong>rushwind</strong> —— RushWind 框架 monorepo（http-binding / gen-http / authn-gate / transport-sse / proto-build / storage-seaorm-support 等），本项目的底座：<a href="https://gitee.com/tx7do/rushwind" target="_blank" rel="noopener noreferrer">Gitee</a> ｜ <a href="https://github.com/tx7do/rushwind" target="_blank" rel="noopener noreferrer">GitHub</a></li><li><strong>rushwind-admin</strong> —— 姊妹项目（Rust 中后台平台，同一框架底座）：<a href="https://gitee.com/tx7do/rushwind-admin" target="_blank" rel="noopener noreferrer">Gitee</a> ｜ <a href="https://github.com/tx7do/rushwind-admin" target="_blank" rel="noopener noreferrer">GitHub</a></li></ul><p>系列文章：</p><ul><li><a href="https://tx7do.github.io/posts/rushwind_admin_intro.html" target="_blank" rel="noopener noreferrer">RushWind Admin — 用 Rust 写的企业级中后台，开源了</a></li><li><a href="https://tx7do.github.io/posts/rushwind_admin_tenant_recycle_bin.html" target="_blank" rel="noopener noreferrer">RushWind Admin — 多租户行级隔离与租户回收站</a></li></ul>`,75)])])}const i=s(p,[["render",o]]),u=JSON.parse('{"path":"/posts/rushwind_cms_three_service_topology.html","title":"RushWind CMS — 三服务拓扑：core 领域层、双 BFF 薄代理与一份契约的双面输出","lang":"zh-CN","frontmatter":{"date":"2026-11-20T00:00:00.000Z","category":["Rust编程"],"tag":["Rust","RushWind","gRPC","架构设计"],"sticky":10},"headers":[{"level":2,"title":"一、三服务分工：数据只有一个主人","slug":"一、三服务分工-数据只有一个主人","link":"#一、三服务分工-数据只有一个主人","children":[]},{"level":2,"title":"二、一份契约，两张脸","slug":"二、一份契约-两张脸","link":"#二、一份契约-两张脸","children":[]},{"level":2,"title":"三、薄代理：BFF 是一张生成的宏表","slug":"三、薄代理-bff-是一张生成的宏表","link":"#三、薄代理-bff-是一张生成的宏表","children":[]},{"level":2,"title":"四、认证链在 core：刷新轮换是一次 Lua 原子操作","slug":"四、认证链在-core-刷新轮换是一次-lua-原子操作","link":"#四、认证链在-core-刷新轮换是一次-lua-原子操作","children":[]},{"level":2,"title":"五、横切件：分页管线与 SSE 扇出","slug":"五、横切件-分页管线与-sse-扇出","link":"#五、横切件-分页管线与-sse-扇出","children":[]},{"level":2,"title":"六、五个前端与两份清单","slug":"六、五个前端与两份清单","link":"#六、五个前端与两份清单","children":[]},{"level":2,"title":"七、E2E：三服务栈上的 125 个断言","slug":"七、e2e-三服务栈上的-125-个断言","link":"#七、e2e-三服务栈上的-125-个断言","children":[]},{"level":2,"title":"八、机制 × 关键决策 × 失败模式","slug":"八、机制-×-关键决策-×-失败模式","link":"#八、机制-×-关键决策-×-失败模式","children":[]}],"git":{"updatedTime":1795147039000,"contributors":[{"name":"Bobo","username":"Bobo","email":"yanglinbo@gmail.com","commits":1,"url":"https://github.com/Bobo"}],"changelog":[{"hash":"16d3c4973313d13612d77376cd8e8b96b7c18718","time":1795147039000,"email":"yanglinbo@gmail.com","author":"Bobo","message":"feat: add posts."}]},"filePathRelative":"posts/rushwind_cms_three_service_topology.md","excerpt":"\\n<blockquote>\\n<p>本文回答一个问题：<strong>一个内容平台为什么要拆成 core-service + 双 BFF 三个进程？BFF 里为什么连一句 SQL 都找不到？同一份 proto 契约又怎么同时长出 REST 和 gRPC 两张脸、喂饱五个前端？</strong></p>\\n</blockquote>\\n<p><a href=\\"https://github.com/tx7do/rushwind-cms\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">RushWind CMS</a> 是一套 Rust 全栈 Headless 内容平台。它的后端是三个进程：<strong>core-service</strong> 是唯一的领域层，独占 PostgreSQL 与 Redis，只对内暴露 gRPC；<strong>admin-api</strong> 与 <strong>app-api</strong> 是两道 BFF，对浏览器与小程序提供 REST + SSE。分工写成一条铁律（仓库根 <code>AGENTS.md</code>）：</p>"}');export{i as comp,u as data};
